import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './Inscripcion.css';

const Inscripcion = ({ cursoId }) => {
  const navigate = useNavigate();

  // Estado para el formulario
  const [formData, setFormData] = useState({
    nombre: '',
    email: '',
    telefono: '',
    edad: '',
    respuestas: [
      { preguntaId: 1, opcionId: '' },
      { preguntaId: 2, opcionId: '' },
      { preguntaId: 3, opcionId: '' },
      { preguntaId: 4, opcionId: '' },
    ], // Respuestas de las preguntas
  });

  // Estado para almacenar las opciones de cada pregunta
  const [opciones, setOpciones] = useState({
    1: [], // Opciones para la pregunta 1 (ocupación)
    2: [], // Opciones para la pregunta 2 (ingresos)
    3: [], // Opciones para la pregunta 3 (objetivos)
    4: [], // Opciones para la pregunta 4 (interés en la academia)
  });

  // Estado para controlar si la inscripción fue exitosa
  const [isInscribed, setIsInscribed] = useState(false);

  // Estado para controlar la visibilidad del slider
  const [showSlider, setShowSlider] = useState(false);

  // Obtener las opciones de las preguntas desde el backend
  useEffect(() => {
    const fetchOpciones = async () => {
      try {
        const response = await fetch('http://localhost:3001/api/opciones');
        const data = await response.json();
        if (response.ok) {
          // Organizar las opciones por pregunta_id
          const opcionesPorPregunta = data.reduce((acc, opcion) => {
            if (!acc[opcion.pregunta_id]) acc[opcion.pregunta_id] = [];
            acc[opcion.pregunta_id].push(opcion);
            return acc;
          }, {});
          setOpciones(opcionesPorPregunta);
        } else {
          console.error('Error al obtener las opciones');
        }
      } catch (error) {
        console.error('Error al obtener las opciones:', error);
      }
    };
    fetchOpciones();
  }, []);

  // Manejar los cambios en los campos del formulario
  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name.startsWith('respuestas')) {
      const [_, preguntaIndex] = name.split('-');
      const updatedRespuestas = [...formData.respuestas];
      updatedRespuestas[preguntaIndex].opcionId = value;
      setFormData({ ...formData, respuestas: updatedRespuestas });
    } else {
      setFormData((prevData) => ({
        ...prevData,
        [name]: value,
      }));
    }
  };

  // Enviar los datos al backend para crear la inscripción
  const handleSubmit = async (e) => {
    e.preventDefault();

    const response = await fetch('http://localhost:3001/api/usuarios/inscribirse', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        ...formData,
        cursoId: cursoId, // Enviar el ID del curso seleccionado
      }),
    });

    const data = await response.json();

    if (response.ok) {
      // Si la inscripción fue exitosa, mostrar el mensaje y ocultar el formulario
      setIsInscribed(true);
      // Mostrar el slider de éxito
      setShowSlider(true);
      // Redirigir después de unos segundos
      setTimeout(() => {
        navigate('/'); // Redirigir a la página de inicio u otra página
      }, 5000); // Redirige después de 5 segundos para mostrar el mensaje
    } else {
      alert('Error al inscribirse');
    }
  };

  return (
    <div className="inscripcion">
      {!isInscribed ? (
        <>
          <h2>Inscribirse al Curso</h2>
          <form onSubmit={handleSubmit}>
            <input
              type="text"
              name="nombre"
              placeholder="Nombre"
              value={formData.nombre}
              onChange={handleChange}
            />
            <input
              type="email"
              name="email"
              placeholder="Email"
              value={formData.email}
              onChange={handleChange}
            />
            <input
              type="text"
              name="telefono"
              placeholder="Teléfono"
              value={formData.telefono}
              onChange={handleChange}
            />
            <input
              type="number"
              name="edad"
              placeholder="Edad"
              value={formData.edad}
              onChange={handleChange}
            />

            {/* Renderizar las preguntas y sus opciones */}
            {Object.keys(opciones).map((preguntaId) => (
              <div key={preguntaId}>
                <label>{`Pregunta ${preguntaId}:`}</label>
                <select
                  name={`respuestas-${preguntaId - 1}`}
                  value={formData.respuestas[preguntaId - 1].opcionId}
                  onChange={handleChange}
                >
                  <option value="">Selecciona una opción</option>
                  {opciones[preguntaId].map((opcion) => (
                    <option key={opcion.id} value={opcion.id}>
                      {opcion.texto}
                    </option>
                  ))}
                </select>
              </div>
            ))}

            <button type="submit">Inscribirse</button>
          </form>
        </>
      ) : (
        <div className="inscripcion-exitosa">
          <h3>¡Inscripción exitosa!</h3>
          <p>Revisa tu correo porque allí recibirás toda la información sobre el curso.</p>
        </div>
      )}

      {/* Slider de confirmación de inscripción */}
      {showSlider && (
        <div className="slider">
          <div className="slider-content">
            <h3>¡Inscripción completada con éxito!</h3>
            <p>Revisa tu correo, ya hemos enviado la información del curso.</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inscripcion;
